"""Password registration and login verification according to org-owasp policy."""
import password_store as _store


def register_password(password: str) -> str:
    """Hash and return a new password string for storage, following current org-owasp policy."""
    # Use the application-facing API for new password hashing.
    # This will use Argon2id with compliant parameters as per current policy.
    return _store.hash_new_password(password)


def check_login(password: str, stored: str) -> bool:
    """Verify a login attempt password against any stored hash format."""
    # Use the application-facing API for verification of any supported stored format.
    return _store.verify_password(password, stored)
